/**
 * Event Bus — in-memory publish/subscribe message broker.
 * Services publish events here; other services subscribe to react to them.
 * No direct service-to-service imports are needed.
 */

type EventCallback = (payload: unknown) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /** Register a callback for a named event. */
  subscribe(event: string, callback: EventCallback): void {
    const existing = this.subscribers.get(event) ?? [];
    this.subscribers.set(event, [...existing, callback]);
  }

  /** Publish an event to all registered subscribers synchronously. */
  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) ?? [];
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        console.error(`[EventBus] Error in subscriber for "${event}":`, err);
      }
    }
  }
}

/** Singleton instance shared across the application. */
export const eventBus = new EventBus();

/**
 * User Service — manages user CRUD operations.
 * Owns its own in-memory store. Publishes no events. Subscribes to no events.
 */

import { randomUUID } from "crypto";

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

export interface User {
  id: string;
  name: string;
  email: string;
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class UserNotFoundError extends Error {
  constructor(id: string) {
    super(`User not found: ${id}`);
    this.name = "UserNotFoundError";
  }
}

export class UserValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "UserValidationError";
  }
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export class UserService {
  /** Service-owned store — no other service may access this directly. */
  private store: Map<string, User> = new Map();

  create(data: { name: string; email: string }): User {
    if (!data.name?.trim()) {
      throw new UserValidationError("name is required");
    }
    if (!data.email?.trim()) {
      throw new UserValidationError("email is required");
    }

    const user: User = {
      id: randomUUID(),
      name: data.name.trim(),
      email: data.email.trim(),
    };

    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) throw new UserNotFoundError(id);
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, data: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);

    if (data.name !== undefined) {
      if (!data.name.trim()) throw new UserValidationError("name cannot be blank");
      user.name = data.name.trim();
    }
    if (data.email !== undefined) {
      if (!data.email.trim()) throw new UserValidationError("email cannot be blank");
      user.email = data.email.trim();
    }

    this.store.set(id, user);
    return user;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new UserNotFoundError(id);
    this.store.delete(id);
  }
}

/** Singleton instance exported for use in the router. */
export const userService = new UserService();

/**
 * Project Service — manages projects and membership.
 * Owns its own in-memory store. Publishes no events. Subscribes to no events.
 */

import { randomUUID } from "crypto";

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class ProjectNotFoundError extends Error {
  constructor(id: string) {
    super(`Project not found: ${id}`);
    this.name = "ProjectNotFoundError";
  }
}

export class ProjectValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ProjectValidationError";
  }
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export class ProjectService {
  /** Service-owned store — no other service may access this directly. */
  private store: Map<string, Project> = new Map();

  create(data: { name: string; description: string }): Project {
    if (!data.name?.trim()) {
      throw new ProjectValidationError("name is required");
    }

    const project: Project = {
      id: randomUUID(),
      name: data.name.trim(),
      description: data.description?.trim() ?? "",
      memberIds: [],
    };

    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) throw new ProjectNotFoundError(id);
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(
    id: string,
    data: Partial<{ name: string; description: string }>
  ): Project {
    const project = this.getById(id);

    if (data.name !== undefined) {
      if (!data.name.trim()) throw new ProjectValidationError("name cannot be blank");
      project.name = data.name.trim();
    }
    if (data.description !== undefined) {
      project.description = data.description.trim();
    }

    this.store.set(id, project);
    return project;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new ProjectNotFoundError(id);
    this.store.delete(id);
  }

  addMember(id: string, userId: string): Project {
    if (!userId?.trim()) {
      throw new ProjectValidationError("userId is required");
    }
    const project = this.getById(id);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.store.set(id, project);
    }
    return project;
  }

  removeMember(id: string, userId: string): Project {
    if (!userId?.trim()) {
      throw new ProjectValidationError("userId is required");
    }
    const project = this.getById(id);
    project.memberIds = project.memberIds.filter((mid) => mid !== userId);
    this.store.set(id, project);
    return project;
  }
}

/** Singleton instance exported for use in the router. */
export const projectService = new ProjectService();

/**
 * Task Service — manages tasks with status transitions.
 * Owns its own in-memory store.
 *
 * Events published:
 *   task.assigned        → { taskId, taskTitle, assigneeId }
 *   task.statusChanged   → { taskId, taskTitle, assigneeId, oldStatus, newStatus }
 */

import { randomUUID } from "crypto";
import { eventBus, EventBus } from "../event-bus.js";

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

// ---------------------------------------------------------------------------
// Status transition rules
// ---------------------------------------------------------------------------

const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

function isValidTransition(from: TaskStatus, to: TaskStatus): boolean {
  const fromIndex = STATUS_ORDER.indexOf(from);
  const toIndex = STATUS_ORDER.indexOf(to);
  return toIndex > fromIndex; // forward-only
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class TaskNotFoundError extends Error {
  constructor(id: string) {
    super(`Task not found: ${id}`);
    this.name = "TaskNotFoundError";
  }
}

export class TaskValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TaskValidationError";
  }
}

export class TaskStatusTransitionError extends Error {
  constructor(from: TaskStatus, to: TaskStatus) {
    super(`Invalid status transition: "${from}" → "${to}". Only forward transitions are allowed (todo → in-progress → done).`);
    this.name = "TaskStatusTransitionError";
  }
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export class TaskService {
  /** Service-owned store — no other service may access this directly. */
  private store: Map<string, Task> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(data: {
    title: string;
    description: string;
    projectId: string;
    assigneeId?: string | null;
  }): Task {
    if (!data.title?.trim()) {
      throw new TaskValidationError("title is required");
    }
    if (!data.projectId?.trim()) {
      throw new TaskValidationError("projectId is required");
    }

    const task: Task = {
      id: randomUUID(),
      title: data.title.trim(),
      description: data.description?.trim() ?? "",
      status: "todo",
      assigneeId: data.assigneeId ?? null,
      projectId: data.projectId.trim(),
    };

    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) throw new TaskNotFoundError(id);
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  update(
    id: string,
    data: Partial<{ title: string; description: string }>
  ): Task {
    const task = this.getById(id);

    if (data.title !== undefined) {
      if (!data.title.trim()) throw new TaskValidationError("title cannot be blank");
      task.title = data.title.trim();
    }
    if (data.description !== undefined) {
      task.description = data.description.trim();
    }

    this.store.set(id, task);
    return task;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new TaskNotFoundError(id);
    this.store.delete(id);
  }

  assign(id: string, assigneeId: string | null): Task {
    const task = this.getById(id);
    task.assigneeId = assigneeId;
    this.store.set(id, task);

    if (assigneeId !== null) {
      this.bus.publish("task.assigned", {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId,
      });
    }

    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task {
    const VALID_STATUSES: TaskStatus[] = ["todo", "in-progress", "done"];
    if (!VALID_STATUSES.includes(newStatus)) {
      throw new TaskValidationError(
        `Invalid status "${newStatus}". Must be one of: ${VALID_STATUSES.join(", ")}`
      );
    }

    const task = this.getById(id);
    const oldStatus = task.status;

    if (oldStatus === newStatus) {
      return task; // no-op, already at that status
    }

    if (!isValidTransition(oldStatus, newStatus)) {
      throw new TaskStatusTransitionError(oldStatus, newStatus);
    }

    task.status = newStatus;
    this.store.set(id, task);

    this.bus.publish("task.statusChanged", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }
}

/** Singleton instance exported for use in the router. */
export const taskService = new TaskService(eventBus);

/**
 * Comment Service — manages comments on tasks.
 * Owns its own in-memory store.
 *
 * Events published:
 *   comment.added → { commentId, taskId, taskTitle, authorId, authorName }
 *
 * The router must supply taskTitle and authorName when calling create(),
 * because the comment service must not call task/user services directly.
 */

import { randomUUID } from "crypto";
import { eventBus, EventBus } from "../event-bus.js";

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class CommentNotFoundError extends Error {
  constructor(id: string) {
    super(`Comment not found: ${id}`);
    this.name = "CommentNotFoundError";
  }
}

export class CommentValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CommentValidationError";
  }
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export class CommentService {
  /** Service-owned store — no other service may access this directly. */
  private store: Map<string, Comment> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  /**
   * Create a comment.
   * `taskTitle` and `authorName` are resolved by the router (which has access
   * to TaskService and UserService) and passed in so that the event payload
   * is enriched without violating service isolation.
   */
  create(data: {
    taskId: string;
    authorId: string;
    body: string;
    /** Denormalised for event payload — resolved by the router. */
    taskTitle: string;
    /** Denormalised for event payload — resolved by the router. */
    authorName: string;
  }): Comment {
    if (!data.taskId?.trim()) {
      throw new CommentValidationError("taskId is required");
    }
    if (!data.authorId?.trim()) {
      throw new CommentValidationError("authorId is required");
    }
    if (!data.body?.trim()) {
      throw new CommentValidationError("body is required");
    }

    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId.trim(),
      authorId: data.authorId.trim(),
      body: data.body.trim(),
      createdAt: new Date().toISOString(),
    };

    this.store.set(comment.id, comment);

    this.bus.publish("comment.added", {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: data.taskTitle,
      authorId: comment.authorId,
      authorName: data.authorName,
    });

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new CommentNotFoundError(id);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new CommentNotFoundError(id);
    this.store.delete(id);
  }
}

/** Singleton instance exported for use in the router. */
export const commentService = new CommentService(eventBus);

/**
 * Notification Service — creates and serves notifications.
 * Owns its own in-memory store.
 *
 * Events subscribed:
 *   task.assigned      → creates notification for assignee
 *   task.statusChanged → creates notification for assignee (if any)
 *   comment.added      → creates notification for task assignee
 *
 * The service subscribes to the event bus in its constructor.
 * The router must pass taskAssigneeId when calling handleCommentAdded so that
 * the notification service does not need to call the task service directly.
 * (In practice this is handled internally via the event payload enriched by
 *  the task service publishing assigneeId on task.statusChanged, and the
 *  comment.added event carrying the task assignee via the router enrichment.)
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ---------------------------------------------------------------------------
// Event payload types (mirror what publishers produce)
// ---------------------------------------------------------------------------

interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: string;
  newStatus: string;
}

interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
  /** Injected by router so notification service knows who to notify. */
  taskAssigneeId: string | null;
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class NotificationNotFoundError extends Error {
  constructor(id: string) {
    super(`Notification not found: ${id}`);
    this.name = "NotificationNotFoundError";
  }
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export class NotificationService {
  /** Service-owned store — no other service may access this directly. */
  private store: Map<string, Notification> = new Map();

  constructor(bus: EventBus) {
    bus.subscribe("task.assigned", (payload) =>
      this.onTaskAssigned(payload as TaskAssignedPayload)
    );
    bus.subscribe("task.statusChanged", (payload) =>
      this.onTaskStatusChanged(payload as TaskStatusChangedPayload)
    );
    bus.subscribe("comment.added", (payload) =>
      this.onCommentAdded(payload as CommentAddedPayload)
    );
  }

  // -------------------------------------------------------------------------
  // Event handlers
  // -------------------------------------------------------------------------

  private onTaskAssigned(payload: TaskAssignedPayload): void {
    this.createNotification(
      payload.assigneeId,
      `You have been assigned to task "${payload.taskTitle}".`
    );
  }

  private onTaskStatusChanged(payload: TaskStatusChangedPayload): void {
    if (!payload.assigneeId) return; // no assignee → nobody to notify
    this.createNotification(
      payload.assigneeId,
      `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`
    );
  }

  private onCommentAdded(payload: CommentAddedPayload): void {
    if (!payload.taskAssigneeId) return; // unassigned task → nobody to notify
    // Don't notify someone who commented on their own task
    if (payload.taskAssigneeId === payload.authorId) return;
    this.createNotification(
      payload.taskAssigneeId,
      `${payload.authorName} commented on task "${payload.taskTitle}": check your tasks for updates.`
    );
  }

  // -------------------------------------------------------------------------
  // Internal helper
  // -------------------------------------------------------------------------

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  // -------------------------------------------------------------------------
  // Public operations
  // -------------------------------------------------------------------------

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) throw new NotificationNotFoundError(id);
    notification.read = true;
    this.store.set(id, notification);
    return notification;
  }
}

/** Singleton — importing this file registers subscriptions on the shared bus. */
import { eventBus } from "../event-bus.js";
export const notificationService = new NotificationService(eventBus);

/**
 * API Router — single HTTP entry point.
 * Parses requests, delegates to services, serialises responses.
 * All HTTP concerns live here; services are pure TypeScript classes.
 */

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";

import { userService } from "./services/user-service.js";
import {
  projectService,
  ProjectNotFoundError,
  ProjectValidationError,
} from "./services/project-service.js";
import {
  taskService,
  TaskNotFoundError,
  TaskValidationError,
  TaskStatusTransitionError,
  TaskStatus,
} from "./services/task-service.js";
import {
  commentService,
  CommentNotFoundError,
  CommentValidationError,
} from "./services/comment-service.js";
import {
  notificationService,
  NotificationNotFoundError,
} from "./services/notification-service.js";
import { UserNotFoundError, UserValidationError } from "./services/user-service.js";

// ---------------------------------------------------------------------------
// Utility helpers
// ---------------------------------------------------------------------------

/** Read the full request body as a string. */
function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

/** Parse JSON body; returns null if empty or invalid. */
async function parseBody<T>(req: IncomingMessage): Promise<T | null> {
  const raw = await readBody(req);
  if (!raw.trim()) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

/** Send a JSON response. */
function json(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

/** Map known error types to HTTP status codes. */
function errorResponse(res: ServerResponse, err: unknown): void {
  if (
    err instanceof UserNotFoundError ||
    err instanceof ProjectNotFoundError ||
    err instanceof TaskNotFoundError ||
    err instanceof CommentNotFoundError ||
    err instanceof NotificationNotFoundError
  ) {
    return json(res, 404, { error: (err as Error).message });
  }
  if (
    err instanceof UserValidationError ||
    err instanceof ProjectValidationError ||
    err instanceof TaskValidationError ||
    err instanceof TaskStatusTransitionError ||
    err instanceof CommentValidationError
  ) {
    return json(res, 400, { error: (err as Error).message });
  }
  console.error("[Router] Unhandled error:", err);
  json(res, 500, { error: "Internal server error" });
}

/** Extract path segments after stripping the leading slash. e.g. "/users/abc" → ["users","abc"] */
function segments(pathname: string): string[] {
  return pathname.replace(/^\//, "").split("/").filter(Boolean);
}

// ---------------------------------------------------------------------------
// Route handler
// ---------------------------------------------------------------------------

export async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse
): Promise<void> {
  const base = `http://${req.headers.host ?? "localhost"}`;
  const url = new URL(req.url ?? "/", base);
  const method = req.method?.toUpperCase() ?? "GET";
  const parts = segments(url.pathname);

  try {
    // -----------------------------------------------------------------------
    // /users[/:id]
    // -----------------------------------------------------------------------
    if (parts[0] === "users") {
      const id = parts[1];

      if (!id) {
        // GET /users
        if (method === "GET") {
          return json(res, 200, userService.getAll());
        }
        // POST /users
        if (method === "POST") {
          const body = await parseBody<{ name: string; email: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          const user = userService.create(body);
          return json(res, 201, user);
        }
      } else {
        // GET /users/:id
        if (method === "GET") {
          return json(res, 200, userService.getById(id));
        }
        // PUT /users/:id
        if (method === "PUT") {
          const body = await parseBody<{ name?: string; email?: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 200, userService.update(id, body));
        }
        // DELETE /users/:id
        if (method === "DELETE") {
          userService.delete(id);
          return json(res, 204, null);
        }
      }
    }

    // -----------------------------------------------------------------------
    // /projects[/:id[/members]]
    // -----------------------------------------------------------------------
    if (parts[0] === "projects") {
      const id = parts[1];
      const sub = parts[2]; // "members" or undefined

      if (!id) {
        // GET /projects
        if (method === "GET") {
          return json(res, 200, projectService.getAll());
        }
        // POST /projects
        if (method === "POST") {
          const body = await parseBody<{ name: string; description: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          const project = projectService.create(body);
          return json(res, 201, project);
        }
      } else if (!sub) {
        // GET /projects/:id
        if (method === "GET") {
          return json(res, 200, projectService.getById(id));
        }
        // PUT /projects/:id
        if (method === "PUT") {
          const body = await parseBody<{ name?: string; description?: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 200, projectService.update(id, body));
        }
        // DELETE /projects/:id
        if (method === "DELETE") {
          projectService.delete(id);
          return json(res, 204, null);
        }
      } else if (sub === "members") {
        // POST /projects/:id/members
        if (method === "POST") {
          const body = await parseBody<{ userId: string }>(req);
          if (!body?.userId) {
            return json(res, 400, { error: "userId is required" });
          }
          return json(res, 200, projectService.addMember(id, body.userId));
        }
        // DELETE /projects/:id/members
        if (method === "DELETE") {
          const body = await parseBody<{ userId: string }>(req);
          if (!body?.userId) {
            return json(res, 400, { error: "userId is required" });
          }
          return json(res, 200, projectService.removeMember(id, body.userId));
        }
      }
    }

    // -----------------------------------------------------------------------
    // /tasks[/:id[/status|/assign]]
    // -----------------------------------------------------------------------
    if (parts[0] === "tasks") {
      const id = parts[1];
      const sub = parts[2]; // "status" | "assign" | undefined

      if (!id) {
        // GET /tasks?projectId=X
        if (method === "GET") {
          const projectId = url.searchParams.get("projectId");
          if (!projectId) {
            return json(res, 400, { error: "projectId query parameter is required" });
          }
          return json(res, 200, taskService.getByProject(projectId));
        }
        // POST /tasks
        if (method === "POST") {
          const body = await parseBody<{
            title: string;
            description: string;
            projectId: string;
            assigneeId?: string | null;
          }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          const task = taskService.create(body);
          return json(res, 201, task);
        }
      } else if (!sub) {
        // GET /tasks/:id
        if (method === "GET") {
          return json(res, 200, taskService.getById(id));
        }
        // PUT /tasks/:id
        if (method === "PUT") {
          const body = await parseBody<{ title?: string; description?: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 200, taskService.update(id, body));
        }
        // DELETE /tasks/:id
        if (method === "DELETE") {
          taskService.delete(id);
          return json(res, 204, null);
        }
      } else if (sub === "status") {
        // PUT /tasks/:id/status
        if (method === "PUT") {
          const body = await parseBody<{ status: TaskStatus }>(req);
          if (!body?.status) {
            return json(res, 400, { error: "status is required" });
          }
          return json(res, 200, taskService.changeStatus(id, body.status));
        }
      } else if (sub === "assign") {
        // PUT /tasks/:id/assign
        if (method === "PUT") {
          const body = await parseBody<{ assigneeId: string | null }>(req);
          if (body === null) {
            return json(res, 400, { error: "Request body is required" });
          }
          // assigneeId may explicitly be null (unassign)
          const assigneeId = body.assigneeId ?? null;
          return json(res, 200, taskService.assign(id, assigneeId));
        }
      }
    }

    // -----------------------------------------------------------------------
    // /comments[/:id]
    // -----------------------------------------------------------------------
    if (parts[0] === "comments") {
      const id = parts[1];

      if (!id) {
        // GET /comments?taskId=X
        if (method === "GET") {
          const taskId = url.searchParams.get("taskId");
          if (!taskId) {
            return json(res, 400, { error: "taskId query parameter is required" });
          }
          return json(res, 200, commentService.getByTask(taskId));
        }
        // POST /comments
        if (method === "POST") {
          const body = await parseBody<{
            taskId: string;
            authorId: string;
            body: string;
          }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });

          // Resolve denormalised data required for the event payload.
          // The router may call multiple services to gather context;
          // services themselves must NOT call each other.
          const task = taskService.getById(body.taskId); // throws TaskNotFoundError if missing
          const author = userService.getById(body.authorId); // throws UserNotFoundError if missing

          const comment = commentService.create({
            taskId: body.taskId,
            authorId: body.authorId,
            body: body.body,
            taskTitle: task.title,
            authorName: author.name,
            // Note: comment.added payload enriched with taskAssigneeId so the
            // notification service knows who to notify without calling taskService.
            // We achieve this by publishing the enriched payload. The commentService
            // already publishes comment.added with taskTitle/authorName; we need
            // taskAssigneeId too. We handle this by re-publishing or by having
            // the notification service receive it from the eventBus payload.
            // Since commentService.create() publishes the event internally,
            // we instead enrich via the eventBus directly after the fact —
            // but that's complex. Instead, the commentService accepts an optional
            // taskAssigneeId field that gets forwarded in the event payload.
          } as Parameters<typeof commentService.create>[0]);

          // The comment.added event was already published by commentService.create().
          // However, we need taskAssigneeId in that event for the notification service.
          // The cleanest approach: publish a supplemental internal event,
          // or restructure so commentService.create() accepts taskAssigneeId.
          // Per our comment-service implementation, we'll publish the enriched version
          // by having commentService accept the field — which it already does via
          // the CommentAddedPayload interface on the notification side.
          // The actual solution: commentService accepts taskAssigneeId as optional
          // extra context for the event. Let's update the flow below.

          return json(res, 201, comment);
        }
      } else {
        // GET /comments/:id
        if (method === "GET") {
          return json(res, 200, commentService.getById(id));
        }
        // DELETE /comments/:id
        if (method === "DELETE") {
          commentService.delete(id);
          return json(res, 204, null);
        }
      }
    }

    // -----------------------------------------------------------------------
    // /notifications[/:id/read]
    // -----------------------------------------------------------------------
    if (parts[0] === "notifications") {
      const id = parts[1];
      const sub = parts[2]; // "read" or undefined

      if (!id) {
        // GET /notifications?userId=X
        if (method === "GET") {
          const userId = url.searchParams.get("userId");
          if (!userId) {
            return json(res, 400, { error: "userId query parameter is required" });
          }
          return json(res, 200, notificationService.getByUser(userId));
        }
      } else if (sub === "read") {
        // PUT /notifications/:id/read
        if (method === "PUT") {
          return json(res, 200, notificationService.markAsRead(id));
        }
      }
    }

    // -----------------------------------------------------------------------
    // 404 — no route matched
    // -----------------------------------------------------------------------
    json(res, 404, { error: `Cannot ${method} ${url.pathname}` });
  } catch (err) {
    errorResponse(res, err);
  }
}

/**
 * Comment Service — manages comments on tasks.
 * Owns its own in-memory store.
 *
 * Events published:
 *   comment.added → { commentId, taskId, taskTitle, authorId, authorName, taskAssigneeId }
 *
 * The router resolves taskTitle, authorName, and taskAssigneeId by consulting
 * TaskService and UserService before calling create(), so the comment service
 * never calls those services directly — preserving service isolation.
 */

import { randomUUID } from "crypto";
import { eventBus, EventBus } from "../event-bus.js";

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class CommentNotFoundError extends Error {
  constructor(id: string) {
    super(`Comment not found: ${id}`);
    this.name = "CommentNotFoundError";
  }
}

export class CommentValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CommentValidationError";
  }
}

// ---------------------------------------------------------------------------
// Input type
// ---------------------------------------------------------------------------

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
  /** Resolved by the router from TaskService — not stored, only forwarded in the event. */
  taskTitle: string;
  /** Resolved by the router from UserService — not stored, only forwarded in the event. */
  authorName: string;
  /** Resolved by the router from TaskService — not stored, only forwarded in the event. */
  taskAssigneeId: string | null;
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export class CommentService {
  /** Service-owned store — no other service may access this directly. */
  private store: Map<string, Comment> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(data: CreateCommentInput): Comment {
    if (!data.taskId?.trim()) {
      throw new CommentValidationError("taskId is required");
    }
    if (!data.authorId?.trim()) {
      throw new CommentValidationError("authorId is required");
    }
    if (!data.body?.trim()) {
      throw new CommentValidationError("body is required");
    }

    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId.trim(),
      authorId: data.authorId.trim(),
      body: data.body.trim(),
      createdAt: new Date().toISOString(),
    };

    this.store.set(comment.id, comment);

    this.bus.publish("comment.added", {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: data.taskTitle,
      authorId: comment.authorId,
      authorName: data.authorName,
      taskAssigneeId: data.taskAssigneeId,
    });

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new CommentNotFoundError(id);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new CommentNotFoundError(id);
    this.store.delete(id);
  }
}

/** Singleton instance exported for use in the router. */
export const commentService = new CommentService(eventBus);

/**
 * API Router — single HTTP entry point.
 * Parses requests, delegates to services, serialises responses.
 * All HTTP concerns live here; services are pure TypeScript classes.
 *
 * The router is the only place that may call multiple services in sequence
 * to gather context (e.g., resolving a task title before creating a comment).
 * Services themselves must NEVER call each other directly.
 */

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";

import {
  userService,
  UserNotFoundError,
  UserValidationError,
} from "./services/user-service.js";
import {
  projectService,
  ProjectNotFoundError,
  ProjectValidationError,
} from "./services/project-service.js";
import {
  taskService,
  TaskNotFoundError,
  TaskValidationError,
  TaskStatusTransitionError,
  TaskStatus,
} from "./services/task-service.js";
import {
  commentService,
  CommentNotFoundError,
  CommentValidationError,
} from "./services/comment-service.js";
import {
  notificationService,
  NotificationNotFoundError,
} from "./services/notification-service.js";

// ---------------------------------------------------------------------------
// Utility helpers
// ---------------------------------------------------------------------------

/** Read the full request body as a UTF-8 string. */
function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

/** Parse JSON body; returns null if body is empty or not valid JSON. */
async function parseBody<T>(req: IncomingMessage): Promise<T | null> {
  const raw = await readBody(req);
  if (!raw.trim()) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

/** Serialise and send a JSON response. */
function json(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

/** Map known domain errors to appropriate HTTP status codes. */
function errorResponse(res: ServerResponse, err: unknown): void {
  if (
    err instanceof UserNotFoundError ||
    err instanceof ProjectNotFoundError ||
    err instanceof TaskNotFoundError ||
    err instanceof CommentNotFoundError ||
    err instanceof NotificationNotFoundError
  ) {
    return json(res, 404, { error: (err as Error).message });
  }
  if (
    err instanceof UserValidationError ||
    err instanceof ProjectValidationError ||
    err instanceof TaskValidationError ||
    err instanceof TaskStatusTransitionError ||
    err instanceof CommentValidationError
  ) {
    return json(res, 400, { error: (err as Error).message });
  }
  console.error("[Router] Unhandled error:", err);
  json(res, 500, { error: "Internal server error" });
}

/**
 * Split a URL pathname into non-empty segments.
 * "/users/abc" → ["users", "abc"]
 */
function pathSegments(pathname: string): string[] {
  return pathname.replace(/^\//, "").split("/").filter(Boolean);
}

// ---------------------------------------------------------------------------
// Main request handler
// ---------------------------------------------------------------------------

export async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse
): Promise<void> {
  const base = `http://${req.headers.host ?? "localhost"}`;
  const url = new URL(req.url ?? "/", base);
  const method = req.method?.toUpperCase() ?? "GET";
  const parts = pathSegments(url.pathname);
  const [resource, id, sub] = parts; // e.g. ["tasks", "abc-123", "status"]

  try {
    // =========================================================================
    // /users  and  /users/:id
    // =========================================================================
    if (resource === "users") {
      if (!id) {
        if (method === "GET") {
          return json(res, 200, userService.getAll());
        }
        if (method === "POST") {
          const body = await parseBody<{ name: string; email: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 201, userService.create(body));
        }
      } else {
        if (method === "GET") {
          return json(res, 200, userService.getById(id));
        }
        if (method === "PUT") {
          const body = await parseBody<{ name?: string; email?: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 200, userService.update(id, body));
        }
        if (method === "DELETE") {
          userService.delete(id);
          return json(res, 204, null);
        }
      }
    }

    // =========================================================================
    // /projects,  /projects/:id,  /projects/:id/members
    // =========================================================================
    if (resource === "projects") {
      if (!id) {
        if (method === "GET") {
          return json(res, 200, projectService.getAll());
        }
        if (method === "POST") {
          const body = await parseBody<{ name: string; description: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 201, projectService.create(body));
        }
      } else if (!sub) {
        if (method === "GET") {
          return json(res, 200, projectService.getById(id));
        }
        if (method === "PUT") {
          const body = await parseBody<{ name?: string; description?: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 200, projectService.update(id, body));
        }
        if (method === "DELETE") {
          projectService.delete(id);
          return json(res, 204, null);
        }
      } else if (sub === "members") {
        if (method === "POST") {
          const body = await parseBody<{ userId: string }>(req);
          if (!body?.userId) {
            return json(res, 400, { error: "userId is required" });
          }
          return json(res, 200, projectService.addMember(id, body.userId));
        }
        if (method === "DELETE") {
          const body = await parseBody<{ userId: string }>(req);
          if (!body?.userId) {
            return json(res, 400, { error: "userId is required" });
          }
          return json(res, 200, projectService.removeMember(id, body.userId));
        }
      }
    }

    // =========================================================================
    // /tasks,  /tasks/:id,  /tasks/:id/status,  /tasks/:id/assign
    // GET /tasks requires ?projectId=X
    // =========================================================================
    if (resource === "tasks") {
      if (!id) {
        if (method === "GET") {
          const projectId = url.searchParams.get("projectId");
          if (!projectId) {
            return json(res, 400, { error: "projectId query parameter is required" });
          }
          return json(res, 200, taskService.getByProject(projectId));
        }
        if (method === "POST") {
          const body = await parseBody<{
            title: string;
            description: string;
            projectId: string;
            assigneeId?: string | null;
          }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 201, taskService.create(body));
        }
      } else if (!sub) {
        if (method === "GET") {
          return json(res, 200, taskService.getById(id));
        }
        if (method === "PUT") {
          const body = await parseBody<{ title?: string; description?: string }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });
          return json(res, 200, taskService.update(id, body));
        }
        if (method === "DELETE") {
          taskService.delete(id);
          return json(res, 204, null);
        }
      } else if (sub === "status") {
        if (method === "PUT") {
          const body = await parseBody<{ status: TaskStatus }>(req);
          if (!body?.status) {
            return json(res, 400, { error: "status is required" });
          }
          return json(res, 200, taskService.changeStatus(id, body.status));
        }
      } else if (sub === "assign") {
        if (method === "PUT") {
          // Body must be present; assigneeId may be null to unassign.
          const body = await parseBody<{ assigneeId: string | null }>(req);
          if (body === null) {
            return json(res, 400, { error: "Request body is required" });
          }
          return json(res, 200, taskService.assign(id, body.assigneeId ?? null));
        }
      }
    }

    // =========================================================================
    // /comments  and  /comments/:id
    // GET /comments requires ?taskId=X
    // POST /comments resolves taskTitle, authorName, taskAssigneeId via router
    // =========================================================================
    if (resource === "comments") {
      if (!id) {
        if (method === "GET") {
          const taskId = url.searchParams.get("taskId");
          if (!taskId) {
            return json(res, 400, { error: "taskId query parameter is required" });
          }
          return json(res, 200, commentService.getByTask(taskId));
        }
        if (method === "POST") {
          const body = await parseBody<{
            taskId: string;
            authorId: string;
            body: string;
          }>(req);
          if (!body) return json(res, 400, { error: "Request body is required" });

          // The router resolves cross-service context so comment service
          // never has to call task or user service directly.
          const task = taskService.getById(body.taskId);   // 404 if missing
          const author = userService.getById(body.authorId); // 404 if missing

          const comment = commentService.create({
            taskId: body.taskId,
            authorId: body.authorId,
            body: body.body,
            taskTitle: task.title,
            authorName: author.name,
            taskAssigneeId: task.assigneeId,
          });

          return json(res, 201, comment);
        }
      } else {
        if (method === "GET") {
          return json(res, 200, commentService.getById(id));
        }
        if (method === "DELETE") {
          commentService.delete(id);
          return json(res, 204, null);
        }
      }
    }

    // =========================================================================
    // /notifications?userId=X  and  /notifications/:id/read
    // =========================================================================
    if (resource === "notifications") {
      if (!id) {
        if (method === "GET") {
          const userId = url.searchParams.get("userId");
          if (!userId) {
            return json(res, 400, { error: "userId query parameter is required" });
          }
          return json(res, 200, notificationService.getByUser(userId));
        }
      } else if (sub === "read") {
        if (method === "PUT") {
          return json(res, 200, notificationService.markAsRead(id));
        }
      }
    }

    // =========================================================================
    // 404 — no route matched
    // =========================================================================
    json(res, 404, { error: `Cannot ${method} ${url.pathname}` });
  } catch (err) {
    errorResponse(res, err);
  }
}

/**
 * Main entry point — creates the HTTP server and starts listening.
 * Run with: npx tsx src/main.ts
 */

import { createServer } from "http";
import { handleRequest } from "./router.js";

const PORT = Number(process.env.PORT ?? 3000);
const HOST = process.env.HOST ?? "127.0.0.1";

const server = createServer((req, res) => {
  handleRequest(req, res).catch((err) => {
    console.error("[Server] Unexpected error:", err);
    if (!res.headersSent) {
      res.writeHead(500, { "Content-Type": "application/json" });
    }
    res.end(JSON.stringify({ error: "Internal server error" }));
  });
});

server.listen(PORT, HOST, () => {
  console.log(`\n🚀  Task Management API is running`);
  console.log(`   Listening on http://${HOST}:${PORT}`);
  console.log(`   Press Ctrl+C to stop\n`);
});

export { server };

