import { createServer, IncomingMessage, ServerResponse } from "http";
import { handleRequest } from "./router.js";

// ---------------------------------------------------------------------------
// Minimal HTTP client (no external deps)
// ---------------------------------------------------------------------------

interface ApiResponse<T = unknown> {
  status: number;
  body: T;
}

function apiCall<T = unknown>(
  method: string,
  path: string,
  body?: unknown
): Promise<ApiResponse<T>> {
  return new Promise((resolve, reject) => {
    const payload = body !== undefined ? JSON.stringify(body) : undefined;
    const options = {
      hostname: "127.0.0.1",
      port: DEMO_PORT,
      path,
      method,
      headers: {
        "Content-Type": "application/json",
        ...(payload ? { "Content-Length": Buffer.byteLength(payload) } : {}),
      },
    };

    const req = (await import("http")).default.request(options, (res: IncomingMessage) => {
      const chunks: Buffer[] = [];
      res.on("data", (chunk: Buffer) => chunks.push(chunk));
      res.on("end", () => {
        const raw = Buffer.concat(chunks).toString("utf8");
        let parsed: T;
        try {
          parsed = JSON.parse(raw) as T;
        } catch {
          parsed = raw as unknown as T;
        }
        resolve({ status: res.statusCode ?? 0, body: parsed });
      });
    });

    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

// ---------------------------------------------------------------------------
// We use Node's built-in http.request via a synchronous-style helper
// ---------------------------------------------------------------------------

import * as http from "http";

function request<T = unknown>(
  method: string,
  path: string,
  body?: unknown
): Promise<ApiResponse<T>> {
  return new Promise((resolve, reject) => {
    const payload = body !== undefined ? JSON.stringify(body) : undefined;
    const options: http.RequestOptions = {
      hostname: "127.0.0.1",
      port: DEMO_PORT,
      path,
      method,
      headers: {
        "Content-Type": "application/json",
        ...(payload ? { "Content-Length": String(Buffer.byteLength(payload)) } : {}),
      },
    };

    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on("data", (chunk: Buffer) => chunks.push(chunk));
      res.on("end", () => {
        const raw = Buffer.concat(chunks).toString("utf8");
        let parsed: T;
        try {
          parsed = JSON.parse(raw) as T;
        } catch {
          parsed = raw as unknown as T;
        }
        resolve({ status: res.statusCode ?? 0, body: parsed });
      });
    });

    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

const DEMO_PORT = 3001;

// ---------------------------------------------------------------------------
// Logging helpers
// ---------------------------------------------------------------------------

const RESET = "\x1b[0m";
const BOLD = "\x1b[1m";
const GREEN = "\x1b[32m";
const RED = "\x1b[31m";
const CYAN = "\x1b[36m";
const YELLOW = "\x1b[33m";
const DIM = "\x1b[2m";

let passCount = 0;
let failCount = 0;

function section(title: string): void {
  console.log(`\n${BOLD}${CYAN}══════════════════════════════════════════${RESET}`);
  console.log(`${BOLD}${CYAN}  ${title}${RESET}`);
  console.log(`${BOLD}${CYAN}══════════════════════════════════════════${RESET}`);
}

function step(description: string): void {
  console.log(`\n${BOLD}▶ ${description}${RESET}`);
}

function assert(
  description: string,
  condition: boolean,
  detail?: unknown
): void {
  if (condition) {
    console.log(`  ${GREEN}✔${RESET} ${description}`);
    passCount++;
  } else {
    console.log(`  ${RED}✘${RESET} ${description}`);
    if (detail !== undefined) {
      console.log(`    ${DIM}Got: ${JSON.stringify(detail)}${RESET}`);
    }
    failCount++;
  }
}

function log(label: string, value: unknown): void {
  console.log(`  ${DIM}${label}:${RESET} ${JSON.stringify(value, null, 2)
    .split("\n")
    .join("\n  ")}`);
}

